//! `--bench-project <out folder> --media <folder>`: the playback benchmark's case projects (SQ-Zukunft/BENCHMARK-DESIGN.md §2.1),
//! generated by code with fixed ids so every machine gets the same project over its own copy of the media.
//! P1: one 4K 10-bit 4:2:2 layer with its sound. P2 (the reported stutter): the same clip plus a 4K clip above it at 50 %,
//! both graded. Media: `bench-main.mp4` and `bench-overlay.mp4`, made or copied by `scripts/sq-bench.sh`.

use sq_core_model::{AnimatedProperty, Clip, ClipEffect, MediaRef, Project, SequenceFormat, Timeline, Track, TrackKind};
use sq_core_time::{Id, Time, TimeRange, Vec2};
use sq_editor_session::ImportBackend;
use std::path::{Path, PathBuf};

/// The media files, in the order `project` takes them.
pub const MEDIA: [&str; 2] = ["bench-main.mp4", "bench-overlay.mp4"];
/// Length of both cases in seconds.
const SECONDS: i64 = 30;

fn id(n: u128) -> Id {
    Id::from_u128(n)
}

fn clip(n: u128, name: &str, media: &MediaRef, kind: TrackKind) -> Clip {
    let mut c = Clip::new(id(n), name, media.id, kind, TimeRange::new(Time::ZERO, Time::seconds(SECONDS)), Time::ZERO);
    c.media_duration = media.duration;
    c
}

fn track(n: u128, kind: TrackKind, name: &str, clips: Vec<Clip>) -> Track {
    let mut t = Track::new(id(n), kind);
    t.name = name.to_string();
    t.set_clips(clips);
    t
}

/// A visible Basic Correction on a clip (a Color effect with its camera LUT): the grade pass runs for real.
fn graded(c: &mut Clip, n: u128) {
    let Some(mut e) = ClipEffect::make(id(n), ClipEffect::COLOR_KIND) else { return };
    for (key, value) in [
        (ClipEffect::COLOR_EXPOSURE_KEY, 0.3),
        (ClipEffect::COLOR_CONTRAST_KEY, 15.0),
        (ClipEffect::COLOR_HIGHLIGHTS_KEY, -20.0),
        (ClipEffect::COLOR_TEMPERATURE_KEY, 8.0),
        (ClipEffect::COLOR_SATURATION_KEY, 115.0),
    ] {
        e.parameters.insert(key.to_string(), AnimatedProperty::new(value));
    }
    c.effects.push(e);
}

/// P1 (`two_layers` false) or P2 (true) over the media of [`MEDIA`], 29.97 fps like the camera clip.
pub fn project(media: &[MediaRef; 2], two_layers: bool) -> Project {
    let [main, overlay] = media;
    let mut base = clip(10, "Main 4K", main, TrackKind::Video);
    let mut tracks = Vec::new();
    if two_layers {
        graded(&mut base, 500);
    }
    tracks.push(track(900, TrackKind::Video, "V1", vec![base]));
    if two_layers {
        let mut top = clip(11, "Overlay 4K", overlay, TrackKind::Video);
        top.animation.scale.value = Vec2::new(0.5, 0.5);
        graded(&mut top, 501);
        tracks.push(track(901, TrackKind::Video, "V2", vec![top]));
    }
    tracks.push(track(910, TrackKind::Audio, "A1", vec![clip(20, "Sound", main, TrackKind::Audio)]));
    let name = if two_layers { "bench-p2" } else { "bench-p1" };
    let timeline = Timeline::new(id(2), name, SequenceFormat::new(Time::new(1001, 30000)), tracks);
    Project::new(id(1), name, media.to_vec(), vec![timeline])
}

/// Writes `bench-p1.sqproj` and `bench-p2.sqproj` into `out`; returns the paths. Media paths are absolute: run it on each machine.
pub fn write_all(out: &Path, folder: &Path) -> Result<Vec<PathBuf>, String> {
    let folder = sq_os::paths::canonical(folder).map_err(|e| format!("{}: {e}", folder.display()))?;
    let probe = crate::probe::FfmpegProbe::default();
    let mut refs = Vec::new();
    for (n, name) in MEDIA.iter().enumerate() {
        let path = folder.join(name);
        if !path.is_file() {
            return Err(format!("{} is missing: run scripts/sq-bench.sh media", path.display()));
        }
        let mut m = probe.probe(&path).map_err(|e| format!("{}: {e:?}", path.display()))?;
        m.id = id(101 + n as u128);
        refs.push(m);
    }
    let media: [MediaRef; 2] = refs.try_into().map_err(|_| "media count".to_string())?;
    std::fs::create_dir_all(out).map_err(|e| format!("{}: {e}", out.display()))?;
    let mut written = Vec::new();
    for (name, two) in [("bench-p1", false), ("bench-p2", true)] {
        let path = out.join(format!("{name}.sqproj"));
        sq_core_project::project_file::project_file()
            .write(&project(&media, two), &path)
            .map_err(|e| format!("{}: {e:?}", path.display()))?;
        written.push(path);
    }
    Ok(written)
}

#[cfg(test)]
mod tests {
    use super::*;
    use sq_core_model::MediaFingerprint;

    fn media() -> [MediaRef; 2] {
        std::array::from_fn(|n| {
            let mut m = MediaRef::new(id(101 + n as u128), MEDIA[n], &format!("/m/{}", MEDIA[n]), MediaFingerprint::new(1));
            m.duration = Some(Time::seconds(40));
            m
        })
    }

    #[test]
    fn p1_is_one_ungraded_layer_and_p2_adds_a_half_size_graded_layer() {
        let (p1, p2) = (project(&media(), false), project(&media(), true));
        let video = |p: &Project| p.timelines[0].tracks.iter().filter(|t| t.kind == TrackKind::Video).count();
        assert_eq!((video(&p1), video(&p2)), (1, 2));
        let top = &p2.timelines[0].tracks[1].clips()[0];
        assert_eq!(top.animation.scale.value, Vec2::new(0.5, 0.5));
        assert!(!top.effects.is_empty());
        assert!(p1.timelines[0].tracks[0].clips()[0].effects.is_empty());
        assert!(!p2.timelines[0].tracks[0].clips()[0].effects.is_empty());
    }
}
